    55→
    56→public class JavaScriptAggregatorFactory extends AggregatorFactory
    57→{
    58→  private final String name;
    59→  private final List<String> fieldNames;
    60→  private final String fnAggregate;
    61→  private final String fnReset;
    62→  private final String fnCombine;
    63→  private final JavaScriptConfig config;
    64→
    65→  /**
    66→   * The field is declared volatile in order to ensure safe publication of the object
    67→   * in {@link #compileScript(String, String, String)} without worrying about final modifiers
    68→   * on the fields of the created object
    69→   *
    70→   * @see <a href="https://github.com/apache/druid/pull/6662#discussion_r237013157">
    71→   *     https://github.com/apache/druid/pull/6662#discussion_r237013157</a>
    72→   */
    73→  private volatile JavaScriptAggregator.@MonotonicNonNull ScriptAggregator compiledScript;
    74→
    75→  @JsonCreator
    76→  public JavaScriptAggregatorFactory(
    77→      @JsonProperty("name") String name,
    78→      @JsonProperty("fieldNames") final List<String> fieldNames,
    79→      @JsonProperty("fnAggregate") final String fnAggregate,
    80→      @JsonProperty("fnReset") final String fnReset,
    81→      @JsonProperty("fnCombine") final String fnCombine,
    82→      @JacksonInject JavaScriptConfig config
    83→  )
    84→  {
    85→    Preconditions.checkNotNull(name, "Must have a valid, non-null aggregator name");
    86→    Preconditions.checkNotNull(fieldNames, "Must have a valid, non-null fieldNames");
    87→    Preconditions.checkNotNull(fnAggregate, "Must have a valid, non-null fnAggregate");
    88→    Preconditions.checkNotNull(fnReset, "Must have a valid, non-null fnReset");
    89→    Preconditions.checkNotNull(fnCombine, "Must have a valid, non-null fnCombine");
    90→
    91→    this.name = name;
    92→    this.fieldNames = fieldNames;
    93→
    94→    this.fnAggregate = fnAggregate;
    95→    this.fnReset = fnReset;
    96→    this.fnCombine = fnCombine;
    97→    this.config = config;
    98→  }
    99→
   100→  @Override
   101→  public Aggregator factorize(final ColumnSelectorFactory columnFactory)
   102→  {
   103→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   104→    return new JavaScriptAggregator(
   105→        fieldNames.stream().map(columnFactory::makeColumnValueSelector).collect(Collectors.toList()),
   106→        compiledScript
   107→    );
   108→  }
   109→
   110→  @Override
   111→  public BufferAggregator factorizeBuffered(final ColumnSelectorFactory columnSelectorFactory)
   112→  {
   113→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   114→    return new JavaScriptBufferAggregator(
   115→        fieldNames.stream().map(columnSelectorFactory::makeColumnValueSelector).collect(Collectors.toList()),
   116→        compiledScript
   117→    );
   118→  }
   119→
   120→  @Override
   121→  public Comparator getComparator()
   122→  {
   123→    return DoubleSumAggregator.COMPARATOR;
   124→  }
   125→
   126→  @Override
   127→  public Object combine(Object lhs, Object rhs)
   128→  {
   129→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   130→    return compiledScript.combine(((Number) lhs).doubleValue(), ((Number) rhs).doubleValue());
   131→  }
   132→
   133→  @Override
   134→  public AggregateCombiner makeAggregateCombiner()
   135→  {
   136→    return new DoubleAggregateCombiner()
   137→    {
   138→      private double combined;
   139→
   140→      @Override
   141→      public void reset(ColumnValueSelector selector)
   142→      {
   143→        combined = selector.getDouble();
   144→      }
   145→
   146→      @Override
   147→      public void fold(ColumnValueSelector selector)
   148→      {
   149→        JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   150→        combined = compiledScript.combine(combined, selector.getDouble());
   151→      }
   152→
   153→      @Override
   154→      public double getDouble()
   155→      {
   156→        return combined;
   157→      }
   158→    };
   159→  }
   160→
   161→  @Override
   162→  public AggregatorFactory getCombiningFactory()
   163→  {
   164→    return new JavaScriptAggregatorFactory(name, Collections.singletonList(name), fnCombine, fnReset, fnCombine, config);
   165→  }
   166→
   167→  @Override
   168→  public AggregatorFactory getMergingFactory(AggregatorFactory other) throws AggregatorFactoryNotMergeableException
   169→  {
   170→    if (other.getName().equals(this.getName()) && other.getClass() == this.getClass()) {
   171→      JavaScriptAggregatorFactory castedOther = (JavaScriptAggregatorFactory) other;
   172→      if (this.fnCombine.equals(castedOther.fnCombine) && this.fnReset.equals(castedOther.fnReset)) {
   173→        return getCombiningFactory();
   174→      }
   175→    }
   176→    throw new AggregatorFactoryNotMergeableException(this, other);
   177→  }
   178→
   179→  @Override
   180→  public List<AggregatorFactory> getRequiredColumns()
   181→  {
   182→    return ImmutableList.copyOf(
   183→        Lists.transform(
   184→            fieldNames,
   185→            new com.google.common.base.Function<String, AggregatorFactory>()
   186→            {
   187→              @Override
   188→              public AggregatorFactory apply(String input)
   189→              {
   190→                return new JavaScriptAggregatorFactory(input, Collections.singletonList(input), fnCombine, fnReset, fnCombine, config);
   191→              }
   192→            }
   193→        )
   194→    );
   195→  }
   196→
   197→  @Override
   198→  public Object deserialize(Object object)
   199→  {
   200→    // handle "NaN" / "Infinity" values serialized as strings in JSON
   201→    if (object instanceof String) {
   202→      return Double.parseDouble((String) object);
   203→    }
   204→    return object;
   205→  }
   206→
   207→  @Nullable
   208→  @Override
   209→  public Object finalizeComputation(@Nullable Object object)
   210→  {
