    20→package org.apache.druid.guice;
    21→
    22→import com.google.common.base.Supplier;
    23→import com.google.common.base.Suppliers;
    24→import com.google.inject.Binder;
    25→import com.google.inject.Inject;
    26→import com.google.inject.Key;
    27→import com.google.inject.Provider;
    28→import com.google.inject.util.Types;
    29→import org.apache.druid.guice.annotations.PublicApi;
    30→
    31→import javax.annotation.Nullable;
    32→import java.lang.annotation.Annotation;
    33→import java.lang.reflect.ParameterizedType;
    34→import java.util.Properties;
    35→
    36→
    37→/**
    38→ * Provides a singleton value of type {@code <T>} from {@code Properties} bound in guice.
    39→ * <br/>
    40→ * <h3>Usage</h3>
    41→ * To install this provider, bind it in your guice module, like below.
    42→ *
    43→ * <pre>
    44→ * JsonConfigProvider.bind(binder, "druid.server", DruidServerConfig.class);
    45→ * </pre>
    46→ * <br/>
    47→ * In the above case, {@code druid.server} should be a key found in the {@code Properties} bound elsewhere.
    48→ * The value of that key should directly relate to the fields in {@code DruidServerConfig.class}.
    49→ *
    50→ * <h3>Implementation</h3>
    51→ * <br/>
    52→ * The state of {@code <T>} is defined by the value of the property {@code propertyBase}.
    53→ * This value is a json structure, decoded via {@link JsonConfigurator#configurate(Properties, String, Class)}.
    54→ * <br/>
    55→ *
    56→ * An example might be if DruidServerConfig.class were
    57→ *
    58→ * <pre>
    59→ *   public class DruidServerConfig
    60→ *   {
    61→ *     @JsonProperty @NotNull public String hostname = null;
    62→ *     @JsonProperty @Min(1025) public int port = 8080;
    63→ *   }
    64→ * </pre>
    65→ *
    66→ * And your Properties object had in it
    67→ *
    68→ * <pre>
    69→ *   druid.server.hostname=0.0.0.0
    70→ *   druid.server.port=3333
    71→ * </pre>
    72→ *
    73→ * Then this would bind a singleton instance of a DruidServerConfig object with hostname = "0.0.0.0" and port = 3333.
    74→ *
    75→ * If the port weren't set in the properties, then the default of 8080 would be taken.  Essentially, it is the same as
    76→ * subtracting the "druid.server" prefix from the properties and building a Map which is then passed into
    77→ * ObjectMapper.convertValue()
    78→ *
    79→ * @param <T> type of config object to provide.
    80→ */
    81→@PublicApi
    82→public class JsonConfigProvider<T> implements Provider<Supplier<T>>
    83→{
    84→  @SuppressWarnings("unchecked")
    85→  public static <T> void bind(Binder binder, String propertyBase, Class<T> classToProvide)
    86→  {
    87→    bind(
    88→        binder,
    89→        propertyBase,
    90→        classToProvide,
    91→        Key.get(classToProvide),
    92→        (Key) Key.get(Types.newParameterizedType(Supplier.class, classToProvide))
    93→    );
    94→  }
    95→
    96→  @SuppressWarnings("unchecked")
    97→  public static <T> void bindWithDefault(
    98→      Binder binder,
    99→      String propertyBase,
   100→      Class<T> classToProvide,
   101→      Class<? extends T> defaultClass
   102→  )
   103→  {
   104→    bind(
   105→        binder,
   106→        propertyBase,
   107→        classToProvide,
   108→        defaultClass,
   109→        Key.get(classToProvide),
   110→        (Key) Key.get(Types.newParameterizedType(Supplier.class, classToProvide))
   111→    );
   112→  }
   113→
   114→  @SuppressWarnings("unchecked")
   115→  public static <T> void bind(Binder binder, String propertyBase, Class<T> classToProvide, Annotation annotation)
   116→  {
   117→    bind(
   118→        binder,
   119→        propertyBase,
   120→        classToProvide,
   121→        Key.get(classToProvide, annotation),
   122→        (Key) Key.get(Types.newParameterizedType(Supplier.class, classToProvide), annotation)
   123→    );
   124→  }
   125→
   126→  @SuppressWarnings("unchecked")
   127→  public static <T> void bind(
   128→      Binder binder,
   129→      String propertyBase,
   130→      Class<T> classToProvide,
   131→      Class<? extends Annotation> annotation
   132→  )
   133→  {
   134→    bind(
   135→        binder,
   136→        propertyBase,
   137→        classToProvide,
   138→        Key.get(classToProvide, annotation),
   139→        (Key) Key.get(Types.newParameterizedType(Supplier.class, classToProvide), annotation)
   140→    );
   141→  }
   142→
   143→  public static <T> void bind(
   144→      Binder binder,
   145→      String propertyBase,
   146→      Class<T> clazz,
   147→      Key<T> instanceKey,
   148→      Key<Supplier<T>> supplierKey
   149→  )
   150→  {
   151→    binder.bind(supplierKey).toProvider(of(propertyBase, clazz)).in(LazySingleton.class);
   152→    binder.bind(instanceKey).toProvider(new SupplierProvider<>(supplierKey));
   153→  }
   154→
   155→  public static <T> void bind(
   156→      Binder binder,
   157→      String propertyBase,
   158→      Class<T> clazz,
   159→      Class<? extends T> defaultClass,
   160→      Key<T> instanceKey,
   161→      Key<Supplier<T>> supplierKey
   162→  )
   163→  {
   164→    binder.bind(supplierKey).toProvider(of(propertyBase, clazz, defaultClass)).in(LazySingleton.class);
   165→    binder.bind(instanceKey).toProvider(new SupplierProvider<>(supplierKey));
   166→  }
   167→
   168→  @SuppressWarnings("unchecked")
   169→  public static <T> void bindInstance(
   170→      Binder binder,
   171→      Key<T> bindKey,
   172→      T instance
   173→  )
   174→  {
   175→    binder.bind(bindKey).toInstance(instance);
   176→
   177→    final ParameterizedType supType = Types.newParameterizedType(Supplier.class, bindKey.getTypeLiteral().getType());
   178→    final Key supplierKey;
   179→
   180→    if (bindKey.getAnnotationType() != null) {
   181→      supplierKey = Key.get(supType, bindKey.getAnnotationType());
   182→    } else if (bindKey.getAnnotation() != null) {
   183→      supplierKey = Key.get(supType, bindKey.getAnnotation());
   184→    } else {
   185→      supplierKey = Key.get(supType);
   186→    }
   187→
   188→    binder.bind(supplierKey).toInstance(Suppliers.ofInstance(instance));
   189→  }
   190→
   191→  public static <T> JsonConfigProvider<T> of(String propertyBase, Class<T> classToProvide)
   192→  {
   193→    return of(propertyBase, classToProvide, null);
   194→  }
   195→
   196→  public static <T> JsonConfigProvider<T> of(
   197→      String propertyBase,
   198→      Class<T> classToProvide,
   199→      Class<? extends T> defaultClass
   200→  )
   201→  {
   202→    return new JsonConfigProvider<>(propertyBase, classToProvide, defaultClass);
   203→  }
   204→
   205→  private final String propertyBase;
   206→  private final Class<T> classToProvide;
   207→  private final Class<? extends T> defaultClass;
   208→
   209→  private Properties props;
   210→  private JsonConfigurator configurator;
   211→
   212→  private Supplier<T> retVal = null;
   213→
   214→  public JsonConfigProvider(
   215→      String propertyBase,
   216→      Class<T> classToProvide,
   217→      @Nullable Class<? extends T> defaultClass
   218→  )
   219→  {
   220→    this.propertyBase = propertyBase;
   221→    this.classToProvide = classToProvide;
   222→    this.defaultClass = defaultClass;
   223→  }
   224→
   225→  @Inject
   226→  public void inject(
   227→      Properties props,
   228→      JsonConfigurator configurator
   229→  )
   230→  {
   231→    this.props = props;
   232→    this.configurator = configurator;
   233→  }
   234→
   235→  @Override
   236→  public Supplier<T> get()
   237→  {
   238→    if (retVal != null) {
   239→      return retVal;
   240→    }
   241→
   242→    try {
   243→      final T config = configurator.configurate(props, propertyBase, classToProvide, defaultClass);
   244→      retVal = Suppliers.ofInstance(config);
   245→    }
   246→    catch (RuntimeException e) {
   247→      // When a runtime exception gets thrown out, this provider will get called again if the object is asked for again.
   248→      // This will have the same failed result, 'cause when it's called no parameters will have actually changed.
   249→      // Guice will then report the same error multiple times, which is pretty annoying. Cache a null supplier and
   250→      // return that instead.  This is technically enforcing a singleton, but such is life.
   251→      retVal = Suppliers.ofInstance(null);
   252→      throw e;
   253→    }
   254→    return retVal;
   255→  }
   256→}
