   121→    if (valueMatcher != null) {
   122→      if (inputRowListPlusRawValues.getInputRows() != null) {
   123→        final List<InputRow> filteredRows = new ArrayList<>(inputRowListPlusRawValues.getInputRows().size());
   124→        for (InputRow inputRow : inputRowListPlusRawValues.getInputRows()) {
